@media(max-width:850px){.club{grid-template-columns:minmax(0,1fr) 215px;gap:20px}.wrap{padding:20px}header{gap:20px}header p:last-child{font-size:16px}}
@media(max-width:650px){.wrap{padding:15px}.edition{font-size:10px;letter-spacing:0}.top{font-size:10px}header{display:block;padding:27px 0 23px}h1{font-size:58px;letter-spacing:-2px}header p:last-child{margin-top:18px;font-size:16px;max-width:100%}.club{display:block}.field-wrap{border-width:5px}.field{aspect-ratio:4/5}.board{top:12px;left:12px;right:12px}.counter{padding:7px 13px}.counter strong{font-size:36px}.card{padding:20px}.card h2{font-size:31px}.footbar{padding:9px;gap:9px}.kick{font-size:18px}aside{padding-top:8px}aside h2{display:none}.statline{margin-bottom:18px}.stamps{grid-template-columns:repeat(3,1fr);gap:7px;margin-top:18px}.stamp{display:block;font-size:10px;text-align:center;padding:9px 5px}.stamp b{display:block;font-size:21px}.rulebook{gap:15px;grid-template-columns:1fr}.rulebook p{margin-top:3px}.rulebook>div{display:grid;grid-template-columns:105px 1fr;gap:10px}footer{display:block}footer p+p{margin-top:12px}.setting{display:inline-block;width:100%}}
