<body>
<div class="wrap">
<nav class="top" aria-label="Main"><a href="./">← Chloe reads Jon</a><span class="edition">FIELD NOTES / No. 201 / OCT 31, 2026</span></nav>
<header>
<div><p class="eyebrow">No shoes required. Excellent socks encouraged.</p><h1>Seawall<br><em>Keep-Up Club</em></h1></div>
<p>A little footbag, a big sky, and absolutely nowhere to be. Keep it off the grass. Give the other foot a turn.</p>
</header>
<main>
<div class="club">
<div>
<div class="field-wrap">
<div class="field" id="field">
<canvas id="court" width="1000" height="667" aria-label="Footbag playfield. Use the left and right kick buttons below, or the left and right arrow keys.">Use the kick buttons below to play.</canvas>
<div class="board"><div class="counter"><strong id="score">0</strong><small>KEEP-UPS</small></div><div class="ticket">SEAWALL PARK<br><span id="flight">OFF DUTY</span></div></div>
<div class="overlay" id="overlay"><div class="card"><span class="label" id="card-label">A pocket-sized park break</span><h2 id="card-title">Shall we keep<br>this thing up?</h2><p id="card-copy">Kick when the bag comes down into the striped band. Alternate feet for a little flair. There is no rush.</p><button class="primary" id="start">Let’s play →</button></div></div>
</div>
<div class="footbar"><button class="kick" id="left">↖ Left foot<small>LEFT ARROW / A</small></button><button class="kick" id="right">Right foot ↗<small>RIGHT ARROW / D</small></button></div>
</div>
<p id="status" class="status" role="status" aria-live="polite">Choose a pace, then meet me on the grass.</p>
</div>
<aside aria-label="Club scorecard">
<h2>Your afternoon off.</h2>
<div class="statline"><div class="stat"><strong id="best">0</strong><span>Best run</span></div><div class="stat"><strong id="rings">0</strong><span>Hoops</span></div><div class="stat"><strong id="alternating">0</strong><span>Foot swaps</span></div></div>
<div class="setting"><label class="label" for="pace">The pace of things</label><select id="pace"><option value="gentle">Gentle · roomy kick window</option><option value="classic">Classic · a quicker rhythm</option></select></div>
<label class="check"><input type="checkbox" id="practice" checked>Practice: drops are no big deal</label>
<div class="controls"><button class="quiet" id="pause" disabled>Pause</button><button class="quiet" id="restart">New run</button><button class="quiet" id="sound" aria-pressed="false">Sound off</button></div>
<p style="font-size:13px;color:var(--mint)">The foot you choose nudges the bag the other way. Aim through the orange hoop on the way up.</p>
<div class="stamps" aria-label="Achievements this visit">
<div class="stamp" id="stamp-five"><b>05</b><span>Five in a row</span></div>
<div class="stamp" id="stamp-swap"><b>↔</b><span>Four foot swaps in a row</span></div>
<div class="stamp" id="stamp-hoop"><b>◎</b><span>Three hoops in one run</span></div>
</div>
</aside>
</div>
<section class="rulebook" aria-label="How to play">
<div><b>01 / WAIT</b><p>Let the bag fall into the striped kick band. The ring beneath it turns green when it is ready.</p></div>
<div><b>02 / TAP</b><p>Use either foot button, tap that half of the park, or press ← / →. Hold nothing. One tap, one kick.</p></div>
<div><b>03 / PLAY</b><p>Try switching feet. Missed it? Practice mode puts it back in your hands. Your best run stays on this device.</p></div>
</section>
</main>
<footer><p>Inspired by Jon’s <a href="?source=1">ideas for things to do when his brother visits</a>, a 2004 list with an aquarium, ice cream, and a game of hacky sack. This one is for the park part.</p><p>A tiny game by Chloe.<br>Original AI-illustrated seawall.</p></footer>
</div>
<script>
'use strict';
const $=id=>document.getElementById(id), canvas=$('court'), ctx=canvas.getContext('2d');
const art=new Image();art.src='?art=1';
let mode='ready',previous=0,x=.5,y=.73,vx=0,vy=0,spin=0,score=0,best=0,hoops=0,swaps=0,lastFoot=null,ringX=.67,ringY=.32,ringHit=false,footFlash=0,flashFoot=0,sound=false,audio=null,dropCount=0;
let earned=new Set(),trail=[],messageTimer=0;
try{best=Math.max(0,Number(localStorage.getItem('seawall-keep-up-best'))||0)}catch{}$('best').textContent=best;
const gentle=()=>$('pace').value==='gentle';
const threshold=()=>gentle()?.47:.60;
const canKick=()=>mode==='playing'&&vy>0&&y>=threshold()&&y<.91;
function announce(s){$('status').textContent=s}
function chime(freq){if(!sound)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.16)}catch{}}
function update(){ $('score').textContent=score;$('rings').textContent=hoops;$('alternating').textContent=swaps;if(score>best){best=score;$('best').textContent=best;try{localStorage.setItem('seawall-keep-up-best',String(best))}catch{}}for(const [id,ok]of [['five',score>=5],['swap',swaps>=4],['hoop',hoops>=3]])if(ok&&!earned.has(id)){earned.add(id);$('stamp-'+id).classList.add('earned');$('stamp-'+id).setAttribute('aria-label','Earned: '+$('stamp-'+id).textContent);announce('Club stamp earned! '+$('stamp-'+id).textContent.trim());}}
function showCard(title,copy,button){$('card-label').textContent='Seawall Keep-Up Club';$('card-title').textContent=title;$('card-copy').textContent=copy;$('start').textContent=button;$('overlay').hidden=false}
function launch(){mode='playing';$('overlay').hidden=true;$('pause').disabled=false;$('pause').textContent='Pause';x=.5;y=.73;vx=0;vy=-.85;ringX=.67;ringHit=false;trail=[];previous=performance.now();$('flight').textContent='IN THE AIR';announce('Wait for the striped band, then tap a foot.');}
function newRun(){score=0;hoops=0;swaps=0;lastFoot=null;dropCount=0;update();launch()}
function kick(foot){
 if(mode!=='playing')return;
 if(!canKick()){announce(vy<0?'Still going up. Let it come back to you.':'Almost. Wait until the bag reaches the striped band.');return}
 score++;swaps=lastFoot!==null&&lastFoot!==foot?swaps+1:0;lastFoot=foot;
 vy=-Math.sqrt(2*1.45*Math.max(.15,y-.25));vx=foot===0?.23:-.23;spin+=foot===0?.5:-.5;ringHit=false;footFlash=.18;flashFoot=foot;
 ringX=score%4<2?.68:.32;ringY=.32;
 announce(swaps?'Nice switch. '+swaps+' foot swap'+(swaps===1?'':'s')+' in a row.':'Clean kick! Try the other foot next.');chime(foot===0?330:440);update();
 const b=$(foot===0?'left':'right');b.classList.add('pressed');setTimeout(()=>b.classList.remove('pressed'),130)
}
function drop(){dropCount++;if($('practice').checked){mode='waiting';$('flight').textContent='TAKE YOUR TIME';$('pause').disabled=true;showCard('Grass happens.','That run: '+score+' keep-ups and '+hoops+' hoops. Your best is '+best+'. The park is still here.','Toss it again →');announce('Bag dropped. Tap Toss it again to begin a fresh run.');}
 else{mode='over';$('flight').textContent='RUN COMPLETE';$('pause').disabled=true;showCard(score>=5?'Nicely played.':'One more go?','You kept it up '+score+' time'+(score===1?'':'s')+' and caught '+hoops+' hoops. Best run: '+best+'.','Try another run →');announce('Run complete. '+score+' keep-ups.');}}
function pause(){if(mode==='playing'){mode='paused';$('pause').textContent='Resume';$('flight').textContent='ON A BREAK';showCard('A good place to pause.','Take your time. Your footbag will wait exactly where you left it.','Back to the park →');announce('Paused.');}else if(mode==='paused'){mode='playing';$('overlay').hidden=true;$('pause').textContent='Pause';$('flight').textContent='IN THE AIR';previous=performance.now();announce('Back in the park.');}}
$('start').onclick=()=>mode==='paused'?pause():newRun();
$('left').onclick=()=>kick(0);$('right').onclick=()=>kick(1);$('pause').onclick=pause;$('restart').onclick=newRun;
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));if(sound)chime(523)};
$('pace').onchange=()=>{if(mode==='playing'||mode==='paused')announce('Pace changed. '+(gentle()?'A slower flight and a wider kick window.':'A quicker flight and a narrower kick window.'));};
canvas.addEventListener('pointerdown',e=>{if(mode==='playing')kick(e.clientX<canvas.getBoundingClientRect().left+canvas.clientWidth/2?0:1)});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(['ArrowLeft','ArrowRight','a','A','d','D',' '].includes(e.key)){e.preventDefault();if(e.repeat)return;if(e.key===' ')pause();else kick(['ArrowLeft','a','A'].includes(e.key)?0:1)}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause()});
function fit(){const box=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(box.width*d);canvas.height=Math.round(box.height*d)}
new ResizeObserver(fit).observe(canvas);
function draw(t){
 const dt=Math.min((t-(previous||t))/1000,.035);previous=t;
 if(mode==='playing'){let step=dt*(gentle()?.65:1);const oldY=y;x+=vx*step;y+=vy*step+.5*1.45*step*step;vy+=1.45*step;spin+=vx*step*5;
 if(x<.055){x=.055;vx=Math.abs(vx)}if(x>.945){x=.945;vx=-Math.abs(vx)}
 if(!ringHit&&vy<0&&oldY>=ringY&&y<=ringY&&Math.abs(x-ringX)<.10){ringHit=true;hoops++;chime(660);announce('Through the hoop! '+hoops+' caught this run.');update()}
 footFlash=Math.max(0,footFlash-dt);if(y>.94)drop();
 }
 const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);
 if(art.complete&&art.naturalWidth){let scale=Math.max(w/art.width,h/art.height);ctx.drawImage(art,(w-art.width*scale)/2,(h-art.height*scale)/2,art.width*scale,art.height*scale)}
 else{ctx.fillStyle='#b9d4bf';ctx.fillRect(0,0,w,h);ctx.fillStyle='#dfbf6e';ctx.fillRect(0,h*.55,w,h*.45)}
 const band=threshold();ctx.fillStyle='#f5edce33';ctx.fillRect(0,h*band,w,h*(.91-band));ctx.strokeStyle='#153f382b';ctx.lineWidth=1;
 for(let n=-h;n<w;n+=22){ctx.beginPath();ctx.moveTo(n,h*.91);ctx.lineTo(n+h*(.91-band),h*band);ctx.stroke()}
 ctx.fillStyle='#153f38';ctx.font=Math.max(9,w*.014)+'px monospace';ctx.fillText('KICK ZONE',w*.035,h*.89);
 if(mode!=='ready'){
 ctx.save();ctx.translate(ringX*w,ringY*h);ctx.strokeStyle=ringHit?'#153f38':'#c44727';ctx.lineWidth=Math.max(4,w*.008);ctx.setLineDash(ringHit?[4,6]:[]);ctx.beginPath();ctx.ellipse(0,0,w*.085,h*.028,-.1,0,Math.PI*2);ctx.stroke();ctx.restore();
 }
 const radius=Math.max(w*.025,10);let bx=x*w,by=y*h;
 ctx.fillStyle='#153f3833';ctx.beginPath();ctx.ellipse(bx,h*.94,radius*(.5+y),radius*.25,0,0,Math.PI*2);ctx.fill();
 ctx.save();ctx.translate(bx,by);ctx.rotate(spin);
 ctx.shadowColor='#153f3870';ctx.shadowBlur=radius*.3;ctx.shadowOffsetY=radius*.18;
 ctx.fillStyle='#f5edce';ctx.beginPath();ctx.arc(0,0,radius,0,Math.PI*2);ctx.fill();ctx.shadowColor='transparent';
 const colors=['#c44727','#e5b943','#153f38','#c44727','#e5b943','#153f38'];
 for(let n=0;n<6;n++){ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,radius,n*Math.PI/3,(n+1)*Math.PI/3);ctx.closePath();ctx.fillStyle=colors[n];ctx.fill();ctx.strokeStyle='#f5edce';ctx.lineWidth=Math.max(1,radius*.055);ctx.stroke()}
 ctx.restore();
 if(canKick()){ctx.strokeStyle='#205642';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(bx,by+radius+8,radius*1.3,radius*.3,0,0,Math.PI*2);ctx.stroke()}
 for(let f=0;f<2;f++){ctx.save();ctx.translate(w*(f===0?.27:.73),h*.97);ctx.rotate(f===0?-.22:.22);ctx.fillStyle=footFlash>0&&flashFoot===f?'#c44727':'#153f38';ctx.beginPath();ctx.ellipse(0,0,w*.075,h*.035,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f5edce';ctx.fillRect(-w*.025,-h*.016,w*.05,h*.007);ctx.restore()}
 requestAnimationFrame(draw);
}
requestAnimationFrame(draw);
</script>
</body>
